// Generated by chart-to-tla.mjs from jevsearch-job.mmd, then edited: the spec's state values are ASCII
// (TLC cannot read non-ASCII strings), so state() draws them with the chart's Japanese captions.
export const regions = ["main"];
const CAPTIONS = {
	Accepted: "受付",
	Normalizing: "正規化",
	Searching: "検索中",
	Failed: "失敗",
	NoResults: "0件",
	RuleTagging: "規則でタグ付け",
	JevClassify: "Jevで分類",
	Saved: "保存済み",
	PartiallySaved: "一部だけ保存",
};
const LABELS = {
	Start: "検索を始めた",
	Normalized: "用語辞書で検索語をそろえ終えた",
	Retry: "検索エンジンにつながらず、1回だけやり直す",
	FailAfterRetry: "やり直しても検索エンジンにつながらず、結果が1件も届かなかった",
	GotZero: "どのエンジンからも結果が返ってこなかった",
	GotResults: "結果が1件以上届いた",
	PartialQueries: "一部の検索語は結果が届き、ほかはやり直してもつながらなかった",
	RuleTagDone: "ドメインで分かる種類を付け終えた",
	AllAnswered: "すべての検索語とエンジンが答え、Jev もすべて答えた",
	EnginesPartial: "一部のエンジンか検索語が答えなかった",
	JevUnavailable: "Jev が使えない、または上限を超えたので未分類として残した",
};

// The actions the reader takes. facts.settled needs them.
export const readerActions = [];
export const state = (v) => regions.map((r) => CAPTIONS[v[r]] ?? v[r]).join(" | ");
export const step = (action) => LABELS[action] ?? action;
